import React, { useState } from 'react';

const Navbar = ({ username, balance, onLogout, setActiveTab, activeTab }) => {
    const [topCategory, setTopCategory] = useState('stocks'); // 'stocks' | 'fno' | 'mf'

    const subTabs = [
        { id: 'explore', label: 'Explore' },
        { id: 'holdings', label: 'Holdings' },
        { id: 'positions', label: 'Positions' },
        { id: 'orders', label: 'Orders' },
        { id: 'watchlist', label: 'Watchlist' },
        { id: 'trading', label: 'Trade & Chart' },
        { id: 'recharge', label: 'Recharge Funds' },
    ];

    return (
        <header style={{
            background: 'var(--bg-surface)',
            borderBottom: '1px solid var(--border-color)',
            position: 'sticky',
            top: 0,
            zIndex: 100,
            boxShadow: 'var(--shadow-soft)'
        }}>
            {/* Top Groww Navigation Row */}
            <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '12px 28px',
                borderBottom: '1px solid var(--border-color)',
                flexWrap: 'wrap',
                gap: '16px'
            }}>
                {/* Groww Logo & Top Category Tabs */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '28px' }}>
                    <div 
                        style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}
                        onClick={() => setActiveTab('explore')}
                    >
                        <div style={{
                            width: '36px',
                            height: '36px',
                            borderRadius: '50%',
                            background: 'linear-gradient(135deg, #38bdf8 0%, #10b981 100%)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: '#ffffff',
                            fontWeight: '800',
                            fontSize: '18px',
                            boxShadow: '0 4px 12px rgba(56, 189, 248, 0.3)'
                        }}>
                            📈
                        </div>
                        <h2 style={{ 
                            margin: 0, 
                            fontSize: '20px', 
                            fontWeight: '800', 
                            background: 'linear-gradient(90deg, #38bdf8, #10b981)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent'
                        }}>
                            Groww Demo
                        </h2>
                    </div>

                    {/* Category Selector Tabs: Stocks | F&O | Mutual Funds */}
                    <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
                        {['stocks', 'fno', 'mf'].map((cat) => {
                            const label = cat === 'stocks' ? 'Stocks' : cat === 'fno' ? 'F&O' : 'Mutual Funds';
                            const isActive = topCategory === cat;
                            return (
                                <button
                                    key={cat}
                                    onClick={() => setTopCategory(cat)}
                                    style={{
                                        background: 'transparent',
                                        border: 'none',
                                        color: isActive ? 'var(--accent-primary)' : 'var(--text-secondary)',
                                        fontSize: '15px',
                                        fontWeight: isActive ? '800' : '600',
                                        cursor: 'pointer',
                                        transition: 'color 0.2s ease'
                                    }}
                                >
                                    {label}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Groww Search & User Bar */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                    {/* Big Groww Search Bar Input at Center */}
                    <div style={{
                        background: '#111927',
                        border: '1px solid var(--border-color)',
                        borderRadius: 'var(--radius-sm)',
                        padding: '8px 16px',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '10px',
                        width: '320px',
                        cursor: 'pointer'
                    }} onClick={() => setActiveTab('trading')}>
                        <span style={{ fontSize: '13px', color: 'var(--text-muted)' }}>🔍</span>
                        <span style={{ fontSize: '13px', color: 'var(--text-muted)', flex: 1 }}>Search Groww....</span>
                        <span style={{
                            fontSize: '10px',
                            background: '#212e44',
                            color: 'var(--text-secondary)',
                            padding: '2px 6px',
                            borderRadius: '4px',
                            fontWeight: '600'
                        }}>Ctrl+K</span>
                    </div>

                    {/* Notification Bell Badge */}
                    <div style={{
                        position: 'relative',
                        background: '#111927',
                        padding: '8px',
                        borderRadius: '50%',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        width: '36px',
                        height: '36px',
                        border: '1px solid var(--border-color)'
                    }}>
                        <span style={{ fontSize: '15px' }}>🔔</span>
                        <span style={{
                            position: 'absolute',
                            top: '-2px',
                            right: '-2px',
                            background: 'var(--accent-rose)',
                            color: '#ffffff',
                            fontSize: '10px',
                            fontWeight: '800',
                            borderRadius: '50%',
                            width: '16px',
                            height: '16px',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center'
                        }}>5</span>
                    </div>

                    {/* Live Balance Pill */}
                    <div style={{
                        background: 'var(--accent-emerald-soft)',
                        border: '1px solid rgba(16, 185, 129, 0.3)',
                        padding: '6px 14px',
                        borderRadius: '20px',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '6px'
                    }}>
                        <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>💰 Demo</span>
                        <span style={{ fontWeight: '800', color: 'var(--accent-emerald)', fontSize: '14px' }}>
                            ₹{(balance || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </span>
                    </div>

                    {/* User Avatar */}
                    <div style={{
                        width: '36px',
                        height: '36px',
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, #818cf8 0%, #38bdf8 100%)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#ffffff',
                        fontWeight: '800',
                        fontSize: '14px',
                        cursor: 'pointer'
                    }} title={username} onClick={onLogout}>
                        {username ? username.charAt(0).toUpperCase() : 'U'}
                    </div>
                </div>
            </div>

            {/* Sub Navigation Bar: Explore | Holdings | Positions | Orders | Watchlist | Terminal */}
            <div style={{
                display: 'flex',
                padding: '0 28px',
                gap: '24px',
                background: 'var(--bg-surface)',
                overflowX: 'auto'
            }}>
                {subTabs.map((tab) => {
                    const isActive = activeTab === tab.id;
                    return (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            style={{
                                padding: '12px 0',
                                background: 'transparent',
                                color: isActive ? 'var(--accent-primary)' : 'var(--text-secondary)',
                                border: 'none',
                                borderBottom: isActive ? '3px solid var(--accent-primary)' : '3px solid transparent',
                                cursor: 'pointer',
                                fontSize: '14px',
                                fontWeight: isActive ? '700' : '600',
                                transition: 'all 0.2s ease',
                                whiteSpace: 'nowrap'
                            }}
                        >
                            {tab.label}
                        </button>
                    );
                })}
            </div>
        </header>
    );
};

export default Navbar;
